import {emotions} from '../content.js';import {shuffle} from '../logic.js';import {gameFrame,roundFlow} from '../ui.js';
export function mountGame(root,c){const flow=roundFlow(root,c);let deck=shuffle(emotions),index=0;function next(){flow.next();if(index>=deck.length){deck=shuffle(emotions);index=0;}const e=deck[index++];const area=gameFrame(root,'Read the expression','Which emotion is this simplified illustration intended to show?');const tone=c.difficulty==='hard'?'#ba8963':'#ecc6a3';area.innerHTML=`<div class="face-illustration"><svg viewBox="0 0 180 180" role="img" aria-label="Illustrated facial expression"><circle cx="90" cy="90" r="75" fill="${tone}"/><path d="${e.brows}" fill="none" stroke="#48382f" stroke-width="5" stroke-linecap="round"/>${[68,112].map(x=>`<ellipse cx="${x}" cy="86" rx="${e.eyes==='wide'?7:4}" ry="${e.eyes==='wide'?9:5}" fill="#48382f"/>`).join('')}<path d="${e.mouth}" fill="${e.label==='Surprised'?'#48382f':'none'}" stroke="#48382f" stroke-width="4" stroke-linecap="round"/></svg></div><div class="emotion-options">${emotions.map(x=>`<button data-emotion="${x.label}">${x.label}</button>`).join('')}</div><p class="subtle">Illustration practice only. Real expressions depend on context.</p>`;area.querySelectorAll('button').forEach(b=>b.onclick=()=>flow.answer(b.dataset.emotion===e.label,`Intended label: ${e.label}. ${e.cue}`,next));}next();return {dispose(){}};}
